请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-003

=== 用户原始指令 (query.txt) ===
帮我弄个低电卡片吧，字浮在背景图上那种，点能跳app，能读日历日程，提醒我快没电了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个低电卡片吧，字浮在背景图上那种，点能跳app，能读日历日程，提醒我快没电了",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModel": {
    "value": {
      "power": {
        "title": "低电模式",
        "warning": "快没电了",
        "actionText": "电池设置"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar_event",
              "entityId": "calendar-low-power-003-1",
              "title": "晚间会议",
              "dtStart": "18:30",
              "dtEnd": "19:00",
              "eventLocation": "线上",
              "description": "低电量时提前充电再参会",
              "senderName": "calendar"
            }
          ]
        }
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "low_power_icon",
      "src": "resources/base/media/icon_save_power.png",
      "use": "low power status icon",
      "description": "省电模式图标，用于低电量提醒卡片中的状态识别和主视觉提示。",
      "static": true
    },
    {
      "assetRef": "battery_background_icon",
      "src": "resources/base/media/icon_electricity.png",
      "use": "ambient battery background",
      "description": "电池图标，用作深色低电背景上的弱化视觉锚点。",
      "static": true
    }
  ]
}

